// Run Once for All Items
// Reads the whole "Org Leads" sheet once and caches known source_ids
// in workflow static data, same pattern as Workflow A's lead cache.
const rows = $input.all();
const existingIds = rows.map(r => r.json.source_id).filter(Boolean);
$getWorkflowStaticData('global').existingOrgIds = existingIds;
return [{ json: { cachedCount: existingIds.length } }];

// Run Once for All Items
// Edit these two lists to match GFIN's actual target categories/states.
const categories = [
  "community foundation",
  "family foundation",
  "food bank",
  "free clinic",
  "housing nonprofit",
  "youth development",
  "arts education nonprofit"
];
const states = ["OH","TX","CA","GA","NC","PA","IL","FL"];

const items = [];
for (const state of states) {
  for (const term of categories) {
    items.push({ json: { searchTerm: term, state, slice: `${term}_${state}`.replace(/\s+/g, '_') } });
  }
}
return items;

// IMPORTANT: keep this on "Run Once for All Items."
// Each input item here is ONE query's full ProPublica response
// (an object with an "organizations" array inside it).
// We flatten every item's organizations[] into its own output row.
// (This is the exact 1:many pattern that bit us before when a node
// was left on "Run Once for Each Item" - don't flip this one.)
const out = [];
for (const item of $input.all()) {
  const orgs = item.json.organizations || [];
  for (const o of orgs) {
    out.push({
      json: {
        source: 'propublica',
        source_id: `ein_${o.ein}`,
        org_name: o.name,
        address: [o.address, o.city, o.state, o.zipcode].filter(Boolean).join(', '),
        city: o.city || null,
        state: o.state || null,
        category: o.ntee_code || o.subseccd || 'nonprofit',
        website: null,
        phone: null,
        ein: o.ein,
        discovered_at: new Date().toISOString()
      }
    });
  }
}
return out;

// Run Once for All Items
// Edit this list to match GFIN's target cities/states.
const cities = [
  { city: "Columbus", state: "OH" },
  { city: "Dallas", state: "TX" },
  { city: "Sacramento", state: "CA" }
];
return cities.map(c => ({ json: { city: c.city, state: c.state, slice: `osm_${c.city}` } }));

// Run Once for Each Item (1:1 - one query string per city)
const { city, state } = $json;
const query = `[out:json][timeout:25];
area["name"="${city}"]["admin_level"~"4|6|8"]->.a;
(
  node["amenity"="place_of_worship"](area.a);
  node["office"~"ngo|charity|association"](area.a);
);
out body;`;
return { json: { ...$json, overpassQuery: query } };

// IMPORTANT: keep this on "Run Once for All Items" - same 1:many
// flatten pattern as the ProPublica normalize node. Each input item
// is one city's full Overpass response (an "elements" array inside).
const out = [];
for (const item of $input.all()) {
  const elements = item.json.elements || [];
  for (const e of elements) {
    const name = e.tags && e.tags.name;
    if (!name) continue; // skip unnamed nodes - not usable as a lead
    out.push({
      json: {
        source: 'osm',
        source_id: `osm_${e.type}_${e.id}`,
        org_name: name,
        address: [
          e.tags['addr:housenumber'], e.tags['addr:street'],
          e.tags['addr:city'], e.tags['addr:state']
        ].filter(Boolean).join(', '),
        city: e.tags['addr:city'] || null,
        state: e.tags['addr:state'] || null,
        category: e.tags.amenity || e.tags.office || 'unknown',
        website: e.tags.website || e.tags['contact:website'] || null,
        phone: e.tags.phone || e.tags['contact:phone'] || null,
        ein: null,
        discovered_at: new Date().toISOString()
      }
    });
  }
}
return out;

// Run Once for All Items
// Edit these to match GFIN's target categories/locations.
const categories = ["church", "nonprofit organization", "community foundation", "economic development office"];
const locations = ["Columbus OH", "Dallas TX", "Sacramento CA"];

const items = [];
for (const cat of categories) {
  for (const loc of locations) {
    items.push({ json: { textQuery: `${cat} in ${loc}`, slice: `${cat}_${loc}`.replace(/\s+/g, '_') } });
  }
}
return items;

// IMPORTANT: keep this on "Run Once for All Items" - same 1:many
// flatten pattern as the other two normalize nodes.
const out = [];
for (const item of $input.all()) {
  const places = item.json.places || [];
  for (const p of places) {
    out.push({
      json: {
        source: 'google_places',
        source_id: `place_${p.id}`,
        org_name: (p.displayName && p.displayName.text) || null,
        address: p.formattedAddress || null,
        city: null,
        state: null,
        category: (p.types || []).join(','),
        // website/phone are intentionally NOT requested - those fields
        // trigger the Enterprise SKU (only 1,000 free calls/mo, then
        // $35-40/1,000). This branch stays on the Pro tier, free up
        // to 5,000 calls/mo.
        website: null,
        phone: null,
        ein: null,
        discovered_at: new Date().toISOString()
      }
    });
  }
}
return out;

// Run Once for All Items
const cached = new Set($getWorkflowStaticData('global').existingOrgIds || []);
const seenThisRun = new Set();
const out = [];
for (const item of $input.all()) {
  const id = item.json.source_id;
  if (!id || cached.has(id) || seenThisRun.has(id)) continue;
  seenThisRun.add(id);
  out.push(item);
}
return out;
